    const NOW: &str = "2026-05-31T11:27:12Z";
    const NAMESPACE: &str = "eu.europa.ec.eudi.pid.1";

    fn compute_ppid(seed: &[u8; 32], verifier_context: &[u8; 32]) -> [u8; 32] {
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        hasher.update(seed);
        hasher.update(verifier_context);
        hasher.finalize().into()
    }

    fn load_v8_2attr_circuit() -> Vec<u8> {
        let compressed = include_bytes!(
            "../../test-vectors/mdoc_zk/8_2_4307_2945_bb8e6a26d2700ddad968562d1c4aee83067772fee6f889748a0bc64f2c694ad5"
        );
        zstd::decode_all(compressed.as_slice()).unwrap()
    }
    /// Mirrors ppid_generation_circuit C++ test
    #[wasm_bindgen_test(unsupported = test)]
    fn test_ppid_prover_succeeds() {
        let circuit = load_v8_2attr_circuit();
        let prover = MdocZkProver::new(&circuit, CircuitVersion::V8, 2)
            .expect("prover construction should succeed");

        let ppid = compute_ppid(&EXPECTED_SEED, &VERIFIER_CONTEXT);

        // Build CBOR-encoded PPID: 0x58 0x20 <32 bytes>
        let mut ppid_cbor = vec![0x58u8, 0x20];
        ppid_cbor.extend_from_slice(&ppid);

        let proof = prover
            .prove_with_ppid(
                MDOC,
                NAMESPACE,
                &["given_name", "pairwise_pseudonym"],
                TRANSCRIPT,
                NOW,
                &VERIFIER_CONTEXT,
            )
            .expect("prover should succeed");

        assert!(!proof.is_empty());
        println!("✅ proof size: {} bytes", proof.len());
        println!(
            "proof (hex): {}",
            proof
                .iter()
                .map(|b| format!("{:02x}", b))
                .collect::<Vec<_>>()
                .join("")
        );
        println!(
            "proof (first 32 bytes): {:02x?}",
            &proof[..32.min(proof.len())]
        );
    }

    /// Mirrors test that prove() without context fails for V8
    #[wasm_bindgen_test(unsupported = test)]
    fn test_v8_prove_without_context_fails() {
        let circuit = load_v8_2attr_circuit();
        let prover = MdocZkProver::new(&circuit, CircuitVersion::V8, 2)
            .expect("prover construction should succeed");

        let result = prover.prove(
            MDOC,
            NAMESPACE,
            &["given_name", "pairwise_pseudonym"],
            TRANSCRIPT,
            NOW,
        );

        assert!(result.is_err(), "V8 prove() without context must fail");
        println!("✅ correctly rejected missing verifier_context");
    }

    #[wasm_bindgen_test(unsupported = test)]
    fn debug_v8_lengths() {
        use crate::mdoc_zk::{CircuitVersion, layout::InputLayout, tests::load_circuits};
        let (sig_circuit, hash_circuit) = load_circuits(CircuitVersion::V8, 2);
        let layout = InputLayout::new(CircuitVersion::V8, 2).unwrap();
        eprintln!("hash circuit inputs: {}", hash_circuit.num_inputs());
        eprintln!("hash layout length:  {}", layout.hash_input_length());
        eprintln!("sig circuit inputs:  {}", sig_circuit.num_inputs());
        eprintln!("sig layout length:   {}", layout.signature_input_length());
        let diff = hash_circuit.num_inputs() as i64 - layout.hash_input_length() as i64;
        eprintln!("hash diff (circuit - layout): {}", diff);
    }

    #[wasm_bindgen_test(unsupported = test)]
    fn debug_ppid_attribute() {
        use crate::mdoc_zk::mdoc::{find_attributes, parse_device_response};
        let mdoc = parse_device_response(MDOC).unwrap();
        // find_attributes() does exact, non-aliased matching; the mdoc's real attribute
        // identifier for the pseudonym seed is "pseudonym_seed" (the "pairwise_pseudonym"
        // name is only used at the public prove_with_ppid()/verify_with_ppid() API layer).
        let attrs = find_attributes(
            &mdoc.attribute_preimages,
            NAMESPACE,
            &["given_name", "pseudonym_seed"],
        )
        .unwrap();
        for (id, attr) in ["given_name", "pseudonym_seed"].iter().zip(attrs.iter()) {
            eprintln!(
                "attr id={} identifier={:?} value_bytes={:02x?} value_len={}",
                id,
                String::from_utf8_lossy(&attr.element_identifier.value),
                attr.element_value.value,
                attr.element_value.value.len(),
            );
        }
    }

    #[wasm_bindgen_test(unsupported = test)]
    fn test_gary_mdoc() {
        let mdoc = hex::decode(GARY_MDOC_HEX).unwrap();
        let transcript = hex::decode("83f6f6847142726f7773657248616e646f76657276315820f93ebac4ce4d9901b9aea472145ae5421f8fbecbe5f0389683f59f08fcf90e455833a363636174016474797065016764657461696c73a1676261736555726c75687474703a2f2f6c6f63616c686f73743a3830383058203c79914b7f81a1c2558fc81619dd4a074d32143e6cf6895fe47da156d1c5b0ae").unwrap();
        let circuit = load_v8_2attr_circuit();
        let prover = MdocZkProver::new(&circuit, CircuitVersion::V8, 2).unwrap();
        let result = prover.prove_with_ppid(
            &mdoc,
            "org.iso.18013.5.1",
            &["family_name", "pairwise_pseudonym"],
            &transcript,
            "2026-05-31T11:27:12Z",
            &VERIFIER_CONTEXT,
        );
        println!("{:?}", result);
        assert!(result.is_ok());
    }

