    fn debug_validity_offsets() {
        use crate::mdoc_zk::mdoc::parse_device_response;

        let eu_mdoc = parse_device_response(MDOC).unwrap();
        eprintln!(
            "EU PID valid_from offset: {}",
            eu_mdoc.mso_offsets.valid_from
        );
        eprintln!(
            "EU PID valid_until offset: {}",
            eu_mdoc.mso_offsets.valid_until
        );

        let mdoc_hex = GARY_MDOC_HEX;
        let gary_mdoc = parse_device_response(&hex::decode(mdoc_hex.trim()).unwrap()).unwrap();
        eprintln!(
            "Gary valid_from offset: {}",
            gary_mdoc.mso_offsets.valid_from
        );
        eprintln!(
            "Gary valid_until offset: {}",
            gary_mdoc.mso_offsets.valid_until
        );

        // Check what bytes are at those offsets in the MSO
        let gary_mso_raw = &gary_mdoc.issuer_signature_payload;
        // gary_mso_raw = tag24(bstr(mso_bytes)), so mso_bytes start at byte 5
        let mso_start = 5; // d8 18 59 02 da = 5 bytes
        let vf_offset = gary_mdoc.mso_offsets.valid_from;
        eprintln!(
            "Gary MSO bytes at valid_from offset {}: {:02x?}",
            vf_offset,
            &gary_mso_raw[mso_start + vf_offset..mso_start + vf_offset + 25]
        );
    }
